rows=[]
for split,before,after in [('validation','baseline_validation','best_validation'),('test','baseline_test','trained_test')]:
    for label,key in [('Before',before),('After',after)]:
        r=results[key];rows.append({'split':split,'model':label,'utterances':r['utterances'],'WER (%)':r['wer']*100,'CER (%)':r['cer']*100})
table=pd.DataFrame(rows);display(table.round(3));table.to_csv(OUT/'metrics.csv',index=False)
fig,axes=plt.subplots(1,2,figsize=(10,3.4))
for ax,metric in zip(axes,['WER (%)','CER (%)']):
    table.pivot(index='split',columns='model',values=metric)[['Before','After']].plot.bar(ax=ax,color=['#aaa2b4','#7c3aed'],rot=0)
    ax.set_ylabel(metric);ax.set_xlabel('');ax.set_title('Lower is better')
fig.tight_layout();fig.savefig(OUT/'before-after.png',dpi=160);plt.show()

run_script('scripts/report_cascade.py')
summary=json.loads((REPORTS/'report/comparison.json').read_text(encoding='utf-8'))
print('Trạng thái:',summary['status'])
print('Còn chờ:',summary['missing_audio'],summary['missing_feedback'])
for filename in ['audio_comparison.csv','feedback_comparison.csv','feedback_by_speaker.csv']:
    path=REPORTS/'report'/filename
    if path.is_file(): display(pd.read_csv(path))
for filename in ['training_curves.png','before_after.png']:
    path=REPORTS/'report'/filename
    if path.is_file(): display(Image(filename=str(path)))
if summary.get('paired_intervals'): display(pd.DataFrame(summary['paired_intervals']).T)
print('HTML:',REPORTS/'report/report.html')

discovered_runs = app.status()["training"]
PLOT_RUN_IDS = list(RUN_IDS.values())
existing_smoke = next((row["run_id"] for row in discovered_runs if row["purpose"] == "technical_smoke_only"), None)
if existing_smoke:
    PLOT_RUN_IDS.append(existing_smoke)
fig, axes = plt.subplots(1, 3, figsize=(16, 4))
plotted = 0
for run_id in PLOT_RUN_IDS:
    directory = ROOT / "runs" / run_id
    if not (directory / "training_log.jsonl").is_file():
        continue
    run_config = read_json(directory / "config.json")
    label = run_id + (" [technical only]" if run_config["purpose"] != "scientific_training" else "")
    history = pd.json_normalize(read_live_log(directory / "training_log.jsonl"))
    if history.empty:
        continue
    history.to_csv(OUT / f"history_{run_id.replace('/', '_')}.csv", index=False)
    axes[0].plot(history.step, history.loss, marker=".", label=label)
    if (directory / "validation_log.jsonl").is_file():
        validation = pd.json_normalize(read_live_log(directory / "validation_log.jsonl"))
        for ax, metric in zip(axes[1:], ["f1", "per"]):
            if not validation.empty:
                ax.plot(validation.step, 100*validation[f"metrics.{metric}"], marker="o", label=label)
    plotted += 1
for ax, title, ylabel in zip(axes, ["Training CTC loss", "Validation F1", "Validation PER"], ["Loss", "%", "%"]):
    ax.set(xlabel="Optimizer update", ylabel=ylabel, title=title)
    if ax.lines:
        ax.legend(fontsize=7)
if plotted:
    show_figure("learning_curves", fig)
else:
    plt.close(fig)
    print("Chưa có log cho các run đã chọn.")

